import{_ as e,o,c as n,ag as a}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/start/phone-documents-list.png",s="/docs/images/start/phone-more-menu.png",i="/docs/images/start/phone-board.png",b=JSON.parse('{"title":"Use Wafflebase on a phone","description":"What you can do in each editor on a phone, where the header and toolbar controls move, and which touch gestures apply.","frontmatter":{"title":"Use Wafflebase on a phone","description":"What you can do in each editor on a phone, where the header and toolbar controls move, and which touch gestures apply.","type":"overview"},"headers":[],"relativePath":"start/phone.md","filePath":"start/phone.md"}'),d={name:"start/phone.md"};function h(l,t,p,g,c,m){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="use-wafflebase-on-a-phone" tabindex="-1">Use Wafflebase on a phone <a class="header-anchor" href="#use-wafflebase-on-a-phone" aria-label="Permalink to &quot;Use Wafflebase on a phone&quot;">​</a></h1><p>Every editor opens and edits on a phone, with a layout made for a narrow screen.</p><p>The phone layout applies when the window is less than 768 pixels wide, so it also appears in a narrow desktop window. The same account, documents, and share links work on every device.</p><h2 id="what-works-on-a-phone" tabindex="-1">What works on a phone <a class="header-anchor" href="#what-works-on-a-phone" aria-label="Permalink to &quot;What works on a phone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Edit</th><th>Comments</th><th>Version history</th><th>Export</th><th>Share</th></tr></thead><tbody><tr><td>Sheets</td><td>Yes</td><td><strong>⋮</strong> menu</td><td><strong>⋮</strong> menu</td><td>Not in the app</td><td>Header</td></tr><tr><td>Docs</td><td>Yes</td><td><strong>⋮</strong> menu</td><td><strong>⋮</strong> menu</td><td><strong>⋮</strong> menu</td><td>Header</td></tr><tr><td>Slides</td><td>Yes</td><td>Not available</td><td>Not on a phone</td><td><strong>⋮</strong> menu</td><td>Header</td></tr><tr><td>Notes</td><td>Yes</td><td>Not available</td><td><strong>⋮</strong> menu</td><td>Not in the app</td><td>Header</td></tr><tr><td>Board</td><td>Yes</td><td><strong>⋮</strong> menu</td><td><strong>⋮</strong> menu</td><td><strong>Download</strong> on the canvas</td><td>Header</td></tr></tbody></table><p>Slides and notes have no comments on any device. Sheets and notes have no export in the app on any device; you can export them from the command line with the CLI. See <a href="/docs/developers/cli/sheets.html#import-and-export-csv-or-json">Import and export CSV or JSON</a> and <a href="/docs/developers/cli/documents.html#read-and-export-a-note">Read and export a note</a>. To use version history for a presentation, open it in a wider window.</p><p>PDFs, images, and other uploaded files open in the same viewer as on a desktop, with download and <strong>Share</strong> in the header.</p><p><img src="'+r+'" alt="Documents list on a phone with the New button and a list of documents"></p><h2 id="find-controls-on-a-phone" tabindex="-1">Find controls on a phone <a class="header-anchor" href="#find-controls-on-a-phone" aria-label="Permalink to &quot;Find controls on a phone&quot;">​</a></h2><ul><li><strong>Sidebar:</strong> tap the sidebar button at the top left to open Documents, Templates, Trash, Settings, and the workspace menu.</li><li><strong>Header:</strong> the document&#39;s own action (the play button, <strong>Slideshow</strong>, in a presentation) and <strong>Share</strong> stay in the header. Tap <strong>⋮</strong> (<strong>More</strong>) for <strong>Comments</strong>, <strong>Version history</strong>, and export. A check mark next to <strong>Comments</strong> or <strong>Version history</strong> shows the panel is open.</li><li><strong>Collaborators:</strong> the avatars of other people in the document are hidden on a phone. Their cursors and selections still appear in the document.</li><li><strong>Toolbar:</strong> each editor shows a shorter toolbar. Swipe it sideways, or open its overflow menu for the rest.</li></ul><p><img src="'+s+'" alt="Document header on a phone with the More menu open showing Comments, Version history, and export formats"></p><h2 id="use-each-editor-on-a-phone" tabindex="-1">Use each editor on a phone <a class="header-anchor" href="#use-each-editor-on-a-phone" aria-label="Permalink to &quot;Use each editor on a phone&quot;">​</a></h2><h3 id="sheets" tabindex="-1">Sheets <a class="header-anchor" href="#sheets" aria-label="Permalink to &quot;Sheets&quot;">​</a></h3><ul><li>Drag with one finger to scroll the grid, and pinch to zoom.</li><li>Double-tap a cell to edit it. Type in the edit panel at the bottom of the screen, then tap the check mark (<strong>Confirm editing</strong>) or the <strong>X</strong> (<strong>Cancel editing</strong>).</li><li>Touch and hold a cell or a selection to open the cell menu, with items such as <strong>Data validation</strong> and <strong>Insert pivot table</strong>.</li><li>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar for number formats, borders, <strong>Create filter</strong>, <strong>Insert chart</strong>, <strong>Insert image</strong>, <strong>Conditional formatting</strong>, and <strong>Data validation</strong>.</li><li>The formula bar and the Name box are hidden. A formula cell shows its formula in the edit panel, but the function list and syntax hint don&#39;t appear there.</li></ul><p>See <a href="/docs/sheets/">Sheets</a>.</p><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Tap to place the cursor and type with the on-screen keyboard.</li><li>The toolbar keeps undo, redo, <strong>Format painter</strong>, bold, italic, underline, the colors, and <strong>Clear formatting</strong>. Swipe it sideways if they don&#39;t all fit.</li><li>Tap ⋮ (<strong>More formatting options</strong>) for fonts, styles, lists and indents, insert, alignment, line spacing, and <strong>Page setup</strong>.</li></ul><p>These need a computer:</p><ul><li>The ruler. Set margins in <strong>Page setup</strong> instead. First-line indents need a wider window.</li><li>Redefining a style. A phone can apply styles but not update or reset them.</li><li>Adding an image by URL. Upload a photo instead.</li><li>A table of any size other than 3 by 3. A phone inserts <strong>Table (3×3)</strong> only.</li><li>Find and replace, which open only from keyboard shortcuts. With a hardware keyboard they work.</li></ul><p>See <a href="/docs/docs-editor/">Docs</a>.</p><h3 id="slides" tabindex="-1">Slides <a class="header-anchor" href="#slides" aria-label="Permalink to &quot;Slides&quot;">​</a></h3><ul><li>The current slide fills the screen, with a strip of slide thumbnails below it. Tap a thumbnail to go to that slide, or tap <strong>Add slide</strong> at the end of the strip to add a blank slide at the end.</li><li>With nothing selected, tap <strong>Insert</strong> (the + icon) for text boxes, images, shapes, lines, and tables.</li><li>Tap an object to select it, and drag its handles to move or resize it. Double-tap a text box or shape to type in it, and touch and hold an object for its menu.</li><li>Theme, format, and background panels open as sheets from the bottom of the screen.</li><li>Tap the play button (<strong>Slideshow</strong>) in the header to present from the current slide. <strong>Present from beginning</strong> is in the header&#39;s ⋮ (<strong>More</strong>) menu.</li></ul><p>Speaker notes, version history, and duplicating, deleting, or reordering slides need a wider window.</p><p>When someone opens a presentation with a viewer link on a phone, they swipe left and right to change slides. See <a href="/docs/slides/">Slides</a>.</p><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>A note shows the editor or the preview, one at a time. Side-by-side <strong>Split</strong> view is not available on a phone.</li><li>Tap the eye icon (<strong>Preview</strong>) in the toolbar to switch between writing and reading. A view you pick on a phone isn&#39;t saved.</li><li>The toolbar keeps undo, redo, the text style, bold, and italic. Tap ⋮ (<strong>More formatting options</strong>) for strikethrough, lists, links, quotes, code blocks, tables, and images.</li><li>A table inserted on a phone is always 3 by 3. Add or remove rows in the source afterward.</li></ul><p>See <a href="/docs/notes/">Notes</a>.</p><h3 id="board" tabindex="-1">Board <a class="header-anchor" href="#board" aria-label="Permalink to &quot;Board&quot;">​</a></h3><ul><li>Drag empty canvas with one finger to move around, and pinch to zoom.</li><li>Tools sit in the dock at the bottom of the screen: <strong>Select</strong>, <strong>Sticky note</strong>, <strong>Text box</strong>, <strong>Shape</strong>, and <strong>Marker</strong>. The rest, such as <strong>Hand</strong>, <strong>Lasso select</strong>, <strong>Line</strong>, <strong>Eraser</strong>, <strong>Section</strong>, <strong>Insert image</strong>, stamps, and <strong>Comment</strong>, are under <strong>More tools</strong> (the ⋯ button).</li><li><strong>Timer</strong>, <strong>Start voting…</strong>, <strong>Spotlight me</strong>, and <strong>Laser pointer</strong> fold into <strong>Facilitate</strong> in the top toolbar when nothing is selected.</li><li>With the marker on, one finger draws and two fingers pinch to zoom.</li><li>Touch and hold empty canvas to open the menu for adding a sticky note or section. Touch and hold an item or a section for its menu.</li><li>The minimap starts closed. Tap <strong>Map</strong> in the bottom right corner to open it.</li><li>Teammates&#39; avatars are hidden, so you can&#39;t start following someone, but you still follow someone who spotlights. Cursor chat and emotes need a keyboard.</li></ul><p>See <a href="/docs/board/">Board</a>.</p><p><img src="'+i+'" alt="Board on a phone with three sticky notes and the tool dock at the bottom"></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/start/getting-started.html">Getting started</a>: build and share your first sheet</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a>: see who else is working in a document</li><li><a href="/docs/start/troubleshooting.html">Troubleshooting</a>: fix saving, share link, and upload problems</li></ul>',33)])])}const f=e(d,[["render",h]]);export{b as __pageData,f as default};
